fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Since we assume `a.len() == b.len()`, we can zip them directly.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| if x == y { '0' } else { '1' })
     .collect()
}

